@@ -1,14 +1,21 @@
 export type Item = { price: number; qty: number };

-const DISCOUNT_THRESHOLD = 100;
+const DISCOUNT_THRESHOLD = 50;
 const DISCOUNT_RATE = 0.1;
+const FREE_SHIPPING_OVER = 75;

 export function subtotal(items: Item[]): number {
   return items.reduce((sum, item) => sum + item.price * item.qty, 0);
 }

+function roundToCents(amount: number): number {
+  return Math.round(amount * 100) / 100;
+}
+
+export function shipsFree(items: Item[]): boolean {
+  return subtotal(items) >= FREE_SHIPPING_OVER;
+}
+
 export function total(items: Item[]): number {
   const sub = subtotal(items);
-  return sub > DISCOUNT_THRESHOLD ? sub * (1 - DISCOUNT_RATE) : sub;
+  return roundToCents(sub > DISCOUNT_THRESHOLD ? sub * (1 - DISCOUNT_RATE) : sub);
 }
